// Cloudflare runtime access. The only module that imports `cloudflare:workers`: application and domain
// code must never import it (ESLint boundary), so they receive these values through ports.
import { env } from 'cloudflare:workers';

/**
 * Returns the typed Worker environment: bindings (DB, MEDIA, CACHE, JOBS, ...) and plain vars.
 * @returns The `Env` object generated by `wrangler types`.
 */
export function getEnv(): Env {
  return env;
}

/**
 * Reads a secret or var by its binding name. Empty strings count as unset.
 * @param name Binding name, for example "STRIPE_SECRET_KEY".
 * @returns The value, or null when it is missing or empty.
 */
export function readSecret(name: string): string | null {
  const value = (env as unknown as Record<string, unknown>)[name];
  return typeof value === 'string' && value !== '' ? value : null;
}

/**
 * Returns the request's ExecutionContext so background work can outlive the response (`waitUntil`).
 * The adapter stores it on `locals.cfContext` for every request.
 * @param locals Astro request locals.
 * @returns The ExecutionContext, or null outside a request.
 */
export function getExecutionContext(locals: { cfContext?: ExecutionContext }): ExecutionContext | null {
  return locals.cfContext ?? null;
}
